/* eclipses.js — every solar and lunar eclipse, about 3001 BC … AD 10001.
   Generated once with Astronomy Engine 2.1.19 (the engine stats.html uses):
   SearchGlobalSolarEclipse / SearchLunarEclipse, peak time in UT days from J2000,
   kind (P partial · A annular · T total · N penumbral) and the zodiac sign of the
   eclipse point (Sun for solar, Moon for lunar). Encoding: first peak in base-36
   centi-days, then per eclipse: base-36 delta (centi-days) + kind letter + sign letter (A=♈ … L=♓). */
(function(root){
function dec(s){const i=s.indexOf('|');let t=parseInt(s.slice(0,i),36);const ut=[],kind=[],sign=[];
  const re=/([0-9a-z]*)([PANT])([A-L])/g;let m,first=true;const body=s.slice(i+1);
  while((m=re.exec(body))){if(!first)t+=parseInt(m[1],36);first=false;ut.push(t/100);kind.push(m[2]);sign.push(m[3].charCodeAt(0)-65);}
  return {ut:Float64Array.from(ut),kind,sign};}
const E={solar:dec("-30rke3|"),lunar:dec("-30rj70|")};
root.ECLIPSES=E;if(typeof module!=='undefined')module.exports=E;
})(typeof window!=='undefined'?window:globalThis);
